const token = String(
  $json.accept_token ??
  $json.query?.accept_token ??
  ''
);

if (!token) {
  return [{
    json: {
      ...$json,
      token_valid_structure: false,
      token_error: 'MISSING_ACCEPT_TOKEN'
    }
  }];
}

const parts = token.split('.');

if (parts.length !== 3) {
  return [{
    json: {
      ...$json,
      token_valid_structure: false,
      token_error: 'INVALID_ACCEPT_TOKEN_FORMAT'
    }
  }];
}

const [leadId, expiryRaw, signature] = parts;
const expiry = Number(expiryRaw);

if (!leadId || !Number.isInteger(expiry) || !signature) {
  return [{
    json: {
      ...$json,
      token_valid_structure: false,
      token_error: 'INVALID_ACCEPT_TOKEN_COMPONENTS'
    }
  }];
}

return [{
  json: {
    ...$json,
    token_valid_structure: true,
    accept_token_lead_id: leadId,
    accept_token_expires_at: expiry,
    accept_token_signature: signature
  }
}];
